CREATE TABLE IF NOT EXISTS kit_extension_schema(version INTEGER PRIMARY KEY CHECK(version=1));
INSERT OR IGNORE INTO kit_extension_schema VALUES(1);
CREATE TABLE IF NOT EXISTS member_role(tenant_id TEXT NOT NULL,actor_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','manager','agent','viewer')),PRIMARY KEY(tenant_id,actor_id));
CREATE TABLE IF NOT EXISTS contact_detail(tenant_id TEXT NOT NULL,contact_id TEXT NOT NULL,email TEXT,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,contact_id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact(tenant_id,id));
CREATE TABLE IF NOT EXISTS channel_identity(tenant_id TEXT NOT NULL,contact_id TEXT NOT NULL,channel TEXT NOT NULL,account_id TEXT NOT NULL,external_id TEXT NOT NULL,PRIMARY KEY(tenant_id,channel,account_id,external_id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact(tenant_id,id));
CREATE TABLE IF NOT EXISTS conversation(tenant_id TEXT NOT NULL,id TEXT NOT NULL,contact_id TEXT NOT NULL,channel TEXT NOT NULL,account_id TEXT NOT NULL DEFAULT '',assigned_actor TEXT,status TEXT NOT NULL DEFAULT 'open',handoff INTEGER NOT NULL DEFAULT 0,last_inbound_at INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact(tenant_id,id));
CREATE TABLE IF NOT EXISTS message_detail(tenant_id TEXT NOT NULL,message_id TEXT NOT NULL,conversation_id TEXT,provider_id TEXT,direction TEXT NOT NULL,actor_id TEXT,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,message_id),FOREIGN KEY(tenant_id,message_id) REFERENCES message(tenant_id,id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversation(tenant_id,id));
CREATE TABLE IF NOT EXISTS channel_event(tenant_id TEXT NOT NULL,channel TEXT NOT NULL,account_id TEXT NOT NULL,event_id TEXT NOT NULL,payload_hash TEXT NOT NULL,PRIMARY KEY(tenant_id,channel,account_id,event_id));
CREATE TABLE IF NOT EXISTS pipeline_stage(tenant_id TEXT NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS lead(tenant_id TEXT NOT NULL,id TEXT NOT NULL,contact_id TEXT NOT NULL,stage_id TEXT NOT NULL,value_cents INTEGER NOT NULL CHECK(value_cents>=0),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact(tenant_id,id),FOREIGN KEY(tenant_id,stage_id) REFERENCES pipeline_stage(tenant_id,id));
CREATE TABLE IF NOT EXISTS tag(tenant_id TEXT NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS contact_tag(tenant_id TEXT NOT NULL,contact_id TEXT NOT NULL,tag_id TEXT NOT NULL,PRIMARY KEY(tenant_id,contact_id,tag_id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact(tenant_id,id),FOREIGN KEY(tenant_id,tag_id) REFERENCES tag(tenant_id,id));
CREATE TABLE IF NOT EXISTS knowledge(tenant_id TEXT NOT NULL,id TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE IF NOT EXISTS quick_reply(tenant_id TEXT NOT NULL,id TEXT NOT NULL,title TEXT NOT NULL,text TEXT NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE IF NOT EXISTS appointment(tenant_id TEXT NOT NULL,id TEXT NOT NULL,contact_id TEXT NOT NULL,resource_id TEXT NOT NULL,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL CHECK(end_at>start_at),status TEXT NOT NULL CHECK(status IN('scheduled','cancelled','completed')),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact(tenant_id,id));
CREATE TABLE IF NOT EXISTS automation_rule(tenant_id TEXT NOT NULL,id TEXT NOT NULL,contains_text TEXT NOT NULL,tag_id TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,tag_id) REFERENCES tag(tenant_id,id));
CREATE TABLE IF NOT EXISTS scheduled_job(tenant_id TEXT NOT NULL,id TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,run_at INTEGER NOT NULL,status TEXT NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE IF NOT EXISTS business_audit(tenant_id TEXT NOT NULL,id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,object_id TEXT,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id));
